  --color-print-yellow: var(--print-yellow);
  --color-print-red: var(--print-red);
  --color-k: var(--k);
  --color-k-ink: var(--k-ink);
  --color-k-hand: var(--k-hand);
  --color-hand-blue: var(--hand-blue);
  --color-hand-violet: var(--hand-violet);
  --color-hand-pink: var(--hand-pink);
  --color-hand-green: var(--hand-green);
  --color-hand-orange: var(--hand-orange);
  --color-hand-red: var(--hand-red);

  --color-background: var(--background);
