import {
  defaultAppearance,
  normalize,
  STORAGE_KEY,
  type Appearance,
} from "./appearance"

/**
 * An inline script for <head> that applies the saved appearance before the first paint, so the page never flashes
 * the wrong paper. Pass the same defaults the app uses at runtime.
 */
export function appearanceScript(defaults: Appearance = defaultAppearance) {
  const fallback = JSON.stringify(normalize(defaults))
  return `(()=>{const d=${fallback};let a=d;try{a={...d,...JSON.parse(localStorage.getItem(${JSON.stringify(STORAGE_KEY)})||"{}")}}catch{}const r=document.documentElement,t=a.theme==="system"?(matchMedia("(prefers-color-scheme: dark)").matches?"night":"day"):a.theme;r.dataset.theme=t==="night"?"night":"day";r.dataset.themePreference=a.theme;r.dataset.stock=a.stock;r.dataset.variation=a.variation;r.dataset.patina=a.patina})()`
}

// Appearance lives as attributes on <html>, so CSS does the work and every island reads the same state.
// Saved choices persist in localStorage; "system" follows the operating system's light or dark setting.

export const APPEARANCE = {
  theme: ["system", "day", "night"],
  stock: ["field", "newsprint"],
  variation: ["calm", "lively"],
  patina: ["clean", "handled", "worn"],
} as const

export type ThemePreference = (typeof APPEARANCE.theme)[number]
export type Stock = (typeof APPEARANCE.stock)[number]
export type Variation = (typeof APPEARANCE.variation)[number]
export type PatinaLevel = (typeof APPEARANCE.patina)[number]

export interface Appearance {
  theme: ThemePreference
  stock: Stock
  variation: Variation
  patina: PatinaLevel
}

export const defaultAppearance: Appearance = {
  theme: "system",
  stock: "field",
  variation: "lively",
  patina: "handled",
}

export const STORAGE_KEY = "patina-appearance"

const pick = <T extends string>(
  options: readonly T[],
  value: unknown,
  fallback: T,
): T => (options.includes(value as T) ? (value as T) : fallback)

/** Keeps only known values, so a stale or hand-edited entry never breaks the page. */
export function normalize(
  value: Partial<Record<keyof Appearance, unknown>>,
  defaults = defaultAppearance,
): Appearance {
  return {
    theme: pick(APPEARANCE.theme, value.theme, defaults.theme),
    stock: pick(APPEARANCE.stock, value.stock, defaults.stock),
    variation: pick(APPEARANCE.variation, value.variation, defaults.variation),
    patina: pick(APPEARANCE.patina, value.patina, defaults.patina),
  }
}

export function readSaved(defaults = defaultAppearance): Appearance {
  try {
    return normalize(
      JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}"),
      defaults,
    )
  } catch {
    return defaults
  }
}

export function save(appearance: Appearance) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appearance))
  } catch {
    // Private windows and blocked storage keep the choice for this page only.
  }
}

export function resolveTheme(theme: ThemePreference): "day" | "night" {
  if (theme !== "system") return theme
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "night"
    : "day"
}

export function apply(
  appearance: Appearance,
  root: HTMLElement = document.documentElement,
) {
  root.dataset.theme = resolveTheme(appearance.theme)
  root.dataset.themePreference = appearance.theme
  root.dataset.stock = appearance.stock
  root.dataset.variation = appearance.variation
  root.dataset.patina = appearance.patina
}

/** The appearance currently applied to the document. */
export function current(
  root: HTMLElement = document.documentElement,
): Appearance {
  const { themePreference, stock, variation, patina } = root.dataset
  return normalize({ theme: themePreference, stock, variation, patina })
}

"use client"

import { useCallback, useSyncExternalStore } from "react"
import {
  apply,
  current,
  defaultAppearance,
  save,
  type Appearance,
} from "./appearance"

let cache: { key: string; value: Appearance } | undefined

function snapshot(): Appearance {
  const value = current()
  const key = JSON.stringify(value)
  if (cache?.key !== key) cache = { key, value }
  return cache.value
}

function subscribe(onChange: () => void) {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: [
      "data-theme-preference",
      "data-stock",
      "data-variation",
      "data-patina",
    ],
  })
  // "system" re-resolves when the operating system switches between light and dark.
  const media = window.matchMedia("(prefers-color-scheme: dark)")
  const follow = () => apply(current())
  media.addEventListener("change", follow)
  return () => {
    observer.disconnect()
    media.removeEventListener("change", follow)
  }
}

/** The document's appearance and a setter that applies and saves a change. Server renders use the defaults. */
export function useAppearance(defaults: Appearance = defaultAppearance) {
  const appearance = useSyncExternalStore(subscribe, snapshot, () => defaults)
  const update = useCallback((change: Partial<Appearance>) => {
    const next = { ...current(), ...change }
    apply(next)
    save(next)
  }, [])
  return [appearance, update] as const
}
